1	/*
2	See the LICENSE.txt file for this sample's licensing information.
3	
4	Abstract:
5	The Liquid Glass browser chrome. A single, stable layout: on focus the address
6	field simply grows taller in place and the tabs shrink into small favicon dots —
7	nothing else moves or changes shape.
8	*/
9	
10	import AppKit
11	import SwiftUI
12	
13	struct BrowserChrome: View {
14	    @Environment(BrowserModel.self) private var browserModel
15	    @Environment(\.accessibilityReduceMotion) private var reduceMotion
16	    let tabLayout: BrowserTabLayout
17	
18	    @State private var isExpanded = false
19	    @FocusState private var fieldFocused: Bool
20	    @State private var collapseTask: Task<Void, Never>?
21	
22	    var body: some View {
23	        VStack(spacing: 0) {
24	            toolbarRow
25	                .zIndex(1)
26	
27	            if tabLayout == .separate {
28	                TabStrip(onPickDot: { collapse() })
29	                    .padding(.horizontal, 12)
30	                    .frame(height: ChromeMetrics.tabBarHeight)
31	            }
32	        }
33	        .frame(maxWidth: .infinity, alignment: .top)
34	        .glassEffect(.regular, in: Rectangle())
35	        .overlay(alignment: .bottom) {
36	            Rectangle()
37	                .fill(Color(nsColor: .separatorColor))
38	                .frame(height: 1)
39	        }
40	        .ignoresSafeArea(edges: .top)
41	        .animation(expandAnimation, value: isExpanded)
42	        .onAppear { requestFocus() }
43	        .onChange(of: browserModel.addressFocusRequestID) { _, _ in requestFocus() }
44	        .onChange(of: fieldFocused) { _, focused in
45	            if focused {
46	                isExpanded = true
47	                startCollapseTimer()
48	            } else {
49	                collapse()
50	            }
51	        }
52	    }
53	
54	    private var expandAnimation: Animation {
55	        reduceMotion
56	            ? .easeInOut(duration: 0.2)
57	            : .smooth(duration: 0.32)
58	    }
59	
60	    // The toolbar row keeps every control exactly where it is. Only the address
61	    // field changes height; controls stay pinned to the top band.
62	    private var toolbarRow: some View {
63	        // Collapsed: the field is centered in the bar. Focused: the field grows
64	        // taller with its top edge fixed, so the chrome grows and the full tab
65	        // strip rides down with it — the tabs themselves are left unchanged.
66	        let inset = (ChromeMetrics.barHeight - ChromeMetrics.controlHeight) / 2
67	        return HStack(alignment: .top, spacing: 8) {
68	            HStack(spacing: 8) {
69	                Color.clear.frame(width: ChromeMetrics.trafficLightGutter)
70	                SidebarTabLayoutButton(tabLayout: tabLayout)
71	                NavigationControls()
72	
73	                if tabLayout == .compact {
74	                    InlineTabStrip(onPickDot: { collapse() })
75	                }
76	            }
77	            .frame(height: ChromeMetrics.barHeight)
78	
79	            AddressField(focused: $fieldFocused, onSubmit: { submit() })
80	                .frame(height: isExpanded ? ChromeMetrics.expandedFieldHeight : ChromeMetrics.controlHeight, alignment: .top)
81	                .padding(.top, inset)
82	                .frame(minWidth: 320, idealWidth: 560, maxWidth: 760)
83	
84	            HStack(spacing: 2) {
85	                ToolbarActions()
86	                PrivateWindowIndicator()
87	            }
88	            .frame(height: ChromeMetrics.barHeight)
89	        }
90	        .padding(.horizontal, 12)
91	        .frame(height: isExpanded ? ChromeMetrics.expandedFieldHeight + inset * 2 : ChromeMetrics.barHeight, alignment: .top)
92	    }
93	
94	    // MARK: - Expand / collapse
95	
96	    private func requestFocus() {
97	        DispatchQueue.main.async { fieldFocused = true }
98	    }
99	
100	    private func collapse() {
101	        cancelCollapseTimer()
102	        guard isExpanded else { return }
103	        isExpanded = false
104	        fieldFocused = false
105	        browserModel.addressText = browserModel.selectedTab?.urlString ?? ""
106	    }
107	
108	    private func submit() {
109	        browserModel.submitAddressBar()
110	        collapse()
111	    }
112	
113	    // Collapses after the pointer has been outside the chrome for 10s, unless
114	    // the field still holds a draft being typed.
115	    private func startCollapseTimer() {
116	        cancelCollapseTimer()
117	        collapseTask = Task { @MainActor in
118	            try? await Task.sleep(for: .seconds(10))
119	            guard Task.isCancelled == false, isExpanded else { return }
120	            if fieldFocused && browserModel.addressText.isEmpty == false {
121	                startCollapseTimer()
122	            } else {
123	                collapse()
124	            }
125	        }
126	    }
127	
128	    private func cancelCollapseTimer() {
129	        collapseTask?.cancel()
130	        collapseTask = nil
131	    }
132	}
133	
134	// MARK: - Controls
135	
136	private struct ChromeIconButton: View {
137	    let title: String
138	    let systemImage: String
139	    var isEnabled: Bool = true
140	    let action: () -> Void
141	
142	    @State private var isHovering = false
143	
144	    var body: some View {
145	        Button(action: action) {
146	            Image(systemName: systemImage)
147	                .font(.system(size: ChromeMetrics.iconSize, weight: .medium))
148	                .frame(width: 30, height: ChromeMetrics.controlHeight)
149	                .contentShape(RoundedRectangle(cornerRadius: ChromeMetrics.controlCornerRadius, style: .continuous))
150	        }
151	        .buttonStyle(.plain)
152	        .foregroundStyle(foreground)
153	        .background {
154	            if isHovering && isEnabled {
155	                RoundedRectangle(cornerRadius: ChromeMetrics.controlCornerRadius, style: .continuous)
156	                    .fill(.quaternary)
157	            }
158	        }
159	        .disabled(isEnabled == false)
160	        .onHover { isHovering = $0 }
161	        .help(title)
162	        .accessibilityLabel(title)
163	    }
164	
165	    private var foreground: AnyShapeStyle {
166	        if isEnabled == false {
167	            return AnyShapeStyle(.tertiary)
168	        }
169	        return AnyShapeStyle(isHovering ? .primary : .secondary)
170	    }
171	}
172	
173	private struct SidebarTabLayoutButton: View {
174	    @Environment(AppPreferences.self) private var appPreferences
175	    let tabLayout: BrowserTabLayout
176	
177	    var body: some View {
178	        ChromeIconButton(
179	            title: tabLayout == .sidebar ? "Hide Sidebar Tabs" : "Show Sidebar Tabs",
180	            systemImage: "sidebar.left"
181	        ) {
182	            withAnimation(.smooth(duration: 0.16)) {
183	                appPreferences.toggleSidebarTabLayout()
184	            }
185	        }
186	    }
187	}
