538	                    Capsule(style: .continuous)
539	                        .strokeBorder(tab.privacyMode.tabModeSelectionColor.opacity(0.4), lineWidth: 1)
540	                }
541	        } else if minimized {
542	            Capsule(style: .continuous)
543	                .fill(.quaternary)
544	        } else if isHovering {
545	            Capsule(style: .continuous)
546	                .fill(.quaternary)
547	        }
