64	private struct WindowCloseObserver: NSViewRepresentable {
65	    let onWindowShouldClose: (@escaping () -> Void) -> Void
66	
67	    func makeCoordinator() -> WindowCloseObserverBox {
68	        WindowCloseObserverBox()
69	    }
70	
71	    func makeNSView(context: Context) -> NSView {
72	        NSView()
73	    }
74	
75	    func updateNSView(_ nsView: NSView, context: Context) {
76	        context.coordinator.onWindowShouldClose = onWindowShouldClose
77	
78	        DispatchQueue.main.async {
79	            context.coordinator.install(window: nsView.window)
80	        }
81	    }
82	
83	    static func dismantleNSView(_ nsView: NSView, coordinator: WindowCloseObserverBox) {
84	        coordinator.remove()
85	    }
86	}
87	
88	@MainActor
89	private final class WindowCloseObserverBox: NSObject, NSWindowDelegate {
90	    var onWindowShouldClose: ((@escaping () -> Void) -> Void)?
91	
92	    private weak var window: NSWindow?
93	    private weak var previousDelegate: (any NSWindowDelegate)?
94	    private var isWaitingForBrowserClose = false
95	
96	    func install(window: NSWindow?) {
97	        guard let window else {
98	            return
99	        }
100	
101	        guard self.window !== window else {
102	            return
103	        }
104	
105	        remove()
106	        self.window = window
107	        previousDelegate = window.delegate
108	        window.delegate = self
109	    }
110	
111	    func remove() {
112	        if let window {
113	            if (window.delegate as AnyObject?) === self {
114	                window.delegate = previousDelegate
115	            }
116	        }
117	
