67	
68	    init(
69	        kind: BrowserWindowKind = .normal,
70	        historyStore: HistoryStore = HistoryStore(),
71	        appPreferences: AppPreferences = AppPreferences(),
72	        tabStore: BrowserTabStore? = nil
73	    ) {
74	        self.kind = kind
75	        self.historyStore = historyStore
76	        self.appPreferences = appPreferences
77	
78	        let resolvedTabStore: BrowserTabStore
79	        if let tabStore {
80	            resolvedTabStore = tabStore
81	        } else if kind.isIncognito {
