145	
146	        close(selectedTab)
147	    }
148	
149	    func close(_ tab: BrowserTab) {
150	        guard let index = tabs.firstIndex(where: { $0.id == tab.id }) else {
151	            return
152	        }
153	
154	        if shouldRememberClosedTab(tab) {
155	            closedTabs.append(tab)
156	        }
157	
158	        let selectedWasClosed = selectedTabID == tab.id
159	        livePageHost.closePage(tabID: tab.id)
160	
161	        tabs.remove(at: index)
162	
163	        if tabs.isEmpty {
164	            selectedTabID = nil
165	            createTab()
166	            return
167	        }
168	
169	        if selectedWasClosed {
170	            let nextIndex = min(index, tabs.count - 1)
171	            selectedTabID = tabs[nextIndex].id
172	        } else {
173	            persistTabs()
174	        }
175	    }
176	
177	    func closeOtherTabs(keeping tab: BrowserTab) {
178	        let removedTabs = tabs.filter { $0.id != tab.id }
179	        guard removedTabs.isEmpty == false else {
180	            return
181	        }
182	
183	        if kind == .normal {
184	            closedTabs.append(contentsOf: removedTabs.filter { shouldRememberClosedTab($0) })
185	        }
186	
187	        livePageHost.closePages(tabIDs: removedTabs.map(\.id))
188	        tabs = [tab]
189	        selectedTabID = tab.id
190	        persistTabs()
191	    }
192	
193	    func toggleTabPin(_ tab: BrowserTab) {
194	        guard let index = tabs.firstIndex(where: { $0.id == tab.id }) else {
195	            return
196	        }
197	
198	        tabs[index].isPinned.toggle()
199	        persistTabs()
200	    }
201	
202	    func toggleSelectedTabPin() {
203	        guard let selectedTab else {
204	            return
205	        }
206	
207	        toggleTabPin(selectedTab)
208	    }
209	
210	    func clearUnpinnedTabs() {
211	        let selectedWasRemoved = selectedTab.map { $0.isPinned == false } ?? false
212	        let removedTabs = tabs.filter { $0.isPinned == false }
213	        let pinnedTabs = tabs.filter(\.isPinned)
214	
215	        guard pinnedTabs.count != tabs.count else {
216	            return
217	        }
218	
219	        if kind == .normal {
220	            closedTabs.append(contentsOf: removedTabs.filter { shouldRememberClosedTab($0) })
221	        }
222	
223	        livePageHost.closePages(tabIDs: removedTabs.map(\.id))
224	        if pinnedTabs.isEmpty {
225	            selectedTabID = nil
226	            createTab()
227	        } else {
228	            let oldSelectedTabID = selectedTabID
229	            tabs = pinnedTabs
230	
231	            if let oldSelectedTabID,
232	               tabs.contains(where: { $0.id == oldSelectedTabID }) {
233	                selectedTabID = oldSelectedTabID
234	            } else {
235	                selectedTabID = tabs.first?.id
236	            }
237	        }
238	
239	        if selectedWasRemoved {
240	            isFindBarVisible = false
241	            findText = ""
242	        }
243	
244	        persistTabs()
245	    }
246	
247	    func reopenLastClosedTab() {
248	        guard kind == .normal, let closedTab = closedTabs.popLast() else {
249	            return
250	        }
251	
252	        var reopenedTab = closedTab
253	        reopenedTab.updatedAt = Date()
254	        tabs.append(reopenedTab)
255	        selectedTabID = reopenedTab.id
256	    }
257	
258	    func selectTab(atZeroBasedIndex index: Int) {
259	        guard tabs.indices.contains(index) else {
260	            return
261	        }
262	
263	        selectedTabID = tabs[index].id
264	    }
265	
266	    func selectPreviousTab() {
267	        guard
268	            let selectedTabID,
269	            let index = tabs.firstIndex(where: { $0.id == selectedTabID }),
270	            index > tabs.startIndex
271	        else {
272	            return
273	        }
274	
275	        self.selectedTabID = tabs[index - 1].id
276	    }
277	
278	    func selectNextTab() {
279	        guard
280	            let selectedTabID,
281	            let index = tabs.firstIndex(where: { $0.id == selectedTabID }),
282	            index < tabs.index(before: tabs.endIndex)
283	        else {
284	            return
285	        }
286	
287	        self.selectedTabID = tabs[index + 1].id
288	    }
289	
290	    func selectRecentTab() {
291	        guard
292	            let previousSelectedTabID,
293	            tabs.contains(where: { $0.id == previousSelectedTabID })
294	        else {
295	            return
296	        }
297	
298	        selectedTabID = previousSelectedTabID
299	    }
300	
301	    func showHistory() {
302	        isHistoryVisible = true
303	    }
304	
305	    func closeHistory() {
306	        isHistoryVisible = false
307	    }
308	
309	    func openHistoryEntry(_ entry: HistoryEntry) {
310	        navigateSelectedTab(to: entry.urlString)
311	        closeHistory()
312	    }
313	
314	    /// Navigates the selected tab to a URL chosen from chrome surfaces such as
315	    /// the start page's Favorites and Frequently Visited tiles.
316	    func openURLString(_ urlString: String) {
317	        navigateSelectedTab(to: urlString)
318	    }
319	
320	    func openContextMenuSearch(for selectedText: String) {
321	        let query = selectedText.trimmingCharacters(in: .whitespacesAndNewlines)
322	        guard query.isEmpty == false else {
323	            return
324	        }
325	
326	        let searchURL = appPreferences.searchEngine.searchURL(for: query)
327	        BrowserPerformanceLog.event("contextMenu.search", metadata: [
328	            "query_length": query.count,
329	            "search_engine": appPreferences.searchEngine.rawValue
330	        ])
331	        createTab(urlString: searchURL, privacyMode: selectedTabPrivacyMode)
332	    }
