334	    func openPopupTab(urlString: String, privacyMode: BrowserTabPrivacyMode) {
335	        let targetURLString = urlString.trimmingCharacters(in: .whitespacesAndNewlines)
336	        guard targetURLString.isEmpty == false else {
337	            return
338	        }
339	
340	        var metadata: [String: Any] = [
341	            "privacy_mode": privacyMode.rawValue
342	        ]
343	        metadata.merge(BrowserPerformanceLog.urlMetadata(targetURLString)) { _, new in new }
344	        BrowserPerformanceLog.event("popup.openTab", metadata: metadata)
345	        createTab(urlString: targetURLString, privacyMode: privacyMode)
346	    }
347	
348	    func copyActivePageURL() {
349	        guard let urlString = activePageSession?.urlString ?? selectedTab?.urlString else {
350	            return
351	        }
352	
353	        NSPasteboard.general.clearContents()
354	        NSPasteboard.general.setString(urlString, forType: .string)
355	    }
356	
357	    func copyActivePageURLAsMarkdown() {
358	        guard let selectedTab, let urlString = selectedTab.urlString else {
359	            return
360	        }
361	
362	        let title = selectedTab.displayTitle
363	            .replacingOccurrences(of: "\\", with: "\\\\")
364	            .replacingOccurrences(of: "]", with: "\\]")
365	        let markdown = "[\(title)](\(urlString))"
366	
367	        NSPasteboard.general.clearContents()
368	        NSPasteboard.general.setString(markdown, forType: .string)
