376	    func zoomIn() {
377	        activePageSession?.zoomIn()
378	    }
379	
380	    func zoomOut() {
381	        activePageSession?.zoomOut()
382	    }
383	
384	    func resetZoom() {
385	        activePageSession?.resetZoom()
386	    }
387	
388	    func showFindInPage() {
389	        isFindBarVisible = true
390	        findFocusRequestID += 1
391	
392	        if findText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false {
393	            runFindInPage(findNext: false, forward: true)
394	        }
395	    }
396	
397	    func closeFindInPage() {
398	        activePageSession?.stopFinding(clearSelection: true)
399	        isFindBarVisible = false
400	    }
401	
402	    func updateFindText(_ text: String) {
403	        findText = text
404	
405	        guard findText.isEmpty == false else {
406	            activePageSession?.stopFinding(clearSelection: true)
407	            return
408	        }
409	
410	        runFindInPage(findNext: false, forward: true)
411	    }
412	
413	    func findNextInPage() {
414	        runFindInPage(findNext: true, forward: true)
415	    }
416	
417	    func findPreviousInPage() {
418	        runFindInPage(findNext: true, forward: false)
