421	    func submitAddressBar() {
422	        let input = addressText.trimmingCharacters(in: .whitespacesAndNewlines)
423	        BrowserPerformanceLog.event("address.submit", metadata: [
424	            "input_length": input.count,
425	            "selected_tab": BrowserPerformanceLog.shortID(selectedTabID)
426	        ])
427	
428	        guard let submission = BrowserInputClassifier.submission(
429	            for: addressText,
430	            searchEngine: appPreferences.searchEngine
431	        ) else {
432	            BrowserPerformanceLog.event("address.submit.ignored", metadata: [
433	                "selected_tab": BrowserPerformanceLog.shortID(selectedTabID)
434	            ])
435	            return
436	        }
437	
438	        switch submission {
439	        case .page(let urlString):
440	            var metadata: [String: Any] = [
441	                "kind": "page",
442	                "selected_tab": BrowserPerformanceLog.shortID(selectedTabID)
443	            ]
444	            metadata.merge(BrowserPerformanceLog.urlMetadata(urlString)) { _, new in new }
445	            BrowserPerformanceLog.event("address.submit.classified", metadata: metadata)
446	            navigateSelectedTab(to: urlString)
447	        case .question(let question):
448	            let answerURL = appPreferences.addressBarAIProvider.responseURL(for: question)
449	            var metadata: [String: Any] = [
450	                "kind": "question",
451	                "answer_provider": appPreferences.addressBarAIProvider.rawValue,
452	                "query_length": question.count,
453	                "selected_tab": BrowserPerformanceLog.shortID(selectedTabID)
454	            ]
455	            metadata.merge(BrowserPerformanceLog.urlMetadata(answerURL)) { _, new in new }
456	            BrowserPerformanceLog.event("address.submit.classified", metadata: metadata)
457	            navigateSelectedTab(to: answerURL)
458	        }
459	    }
460	
461	    func closeBrowsersForWindowClose(completion: @escaping () -> Void) {
462	        guard didCloseBrowsersForWindowClose == false else {
463	            if windowCloseCompletion == nil {
464	                completion()
465	            }
466	            return
467	        }
468	
469	        didCloseBrowsersForWindowClose = true
470	        isFindBarVisible = false
471	        isHistoryVisible = false
472	        findText = ""
473	        windowCloseCompletion = completion
474	
475	        if let pageSession = activePageSession {
476	            let originalOnBrowserClose = pageSession.onBrowserClose
477	            pageSession.onBrowserClose = { [weak self] in
478	                originalOnBrowserClose?()
479	                self?.finishWindowCloseIfNeeded()
480	            }
481	        } else {
482	            finishWindowCloseIfNeeded()
483	        }
484	
485	        livePageHost.closeCachedPagesForWindowClose()
486	
487	        DispatchQueue.main.asyncAfter(deadline: .now() + 2) { [weak self] in
488	            self?.finishWindowCloseIfNeeded()
489	        }
490	    }
491	
492	    private var selectedTabIndex: Int? {
493	        guard let selectedTabID else {
494	            return nil
495	        }
496	
497	        return tabs.firstIndex { $0.id == selectedTabID }
498	    }
499	
500	    private var defaultPrivacyMode: BrowserTabPrivacyMode {
501	        kind.isIncognito ? .incognito : .normal
502	    }
503	
504	    private var selectedTabPrivacyMode: BrowserTabPrivacyMode {
505	        selectedTab.map(effectivePrivacyMode(for:)) ?? defaultPrivacyMode
506	    }
507	
508	    private func navigateSelectedTab(to urlString: String) {
509	        var metadata: [String: Any] = [
510	            "selected_tab": BrowserPerformanceLog.shortID(selectedTabID),
511	            "has_active_session": activePageSession != nil
512	        ]
513	        metadata.merge(BrowserPerformanceLog.urlMetadata(urlString)) { _, new in new }
514	        BrowserPerformanceLog.event("tab.navigateSelected.start", metadata: metadata)
515	
516	        if selectedTabIndex == nil {
517	            BrowserPerformanceLog.event("tab.navigateSelected.createsTab", metadata: metadata)
518	            createTab(urlString: urlString)
519	            return
520	        }
521	
522	        guard let index = selectedTabIndex else {
523	            BrowserPerformanceLog.event("tab.navigateSelected.noSelection", metadata: metadata)
524	            return
525	        }
526	
527	        tabs[index].update(urlString: urlString, title: nil, faviconURLString: nil)
528	        addressText = urlString
529	        persistTabs()
530	
531	        if activePageSession?.tabID == tabs[index].id {
532	            BrowserPerformanceLog.event("tab.navigateSelected.activeSession", metadata: [
533	                "tab": BrowserPerformanceLog.shortID(tabs[index].id)
534	            ])
535	            activePageSession?.navigate(to: urlString)
536	        } else {
537	            BrowserPerformanceLog.event("tab.navigateSelected.activateSession", metadata: [
538	                "tab": BrowserPerformanceLog.shortID(tabs[index].id)
539	            ])
540	            activateSelectedTabPage()
541	        }
542	    }
543	
544	    private func activateSelectedTabPage() {
545	        guard let selectedTab else {
546	            BrowserPerformanceLog.event("tab.activateSelected.empty")
547	            livePageHost.closeActivePage()
548	            return
549	        }
550	
551	        var metadata: [String: Any] = [
552	            "tab": BrowserPerformanceLog.shortID(selectedTab.id),
553	            "is_incognito": effectivePrivacyMode(for: selectedTab).isEphemeral,
554	            "privacy_mode": effectivePrivacyMode(for: selectedTab).rawValue
555	        ]
556	        metadata.merge(BrowserPerformanceLog.urlMetadata(selectedTab.urlString)) { _, new in new }
557	        BrowserPerformanceLog.event("tab.activateSelected.start", metadata: metadata)
558	
559	        livePageHost.activate(
560	            tab: selectedTab,
561	            privacyMode: effectivePrivacyMode(for: selectedTab),
562	            torConfiguration: appPreferences.torConfiguration
563	        ) { [weak self] pageSession in
564	            self?.configurePageCallbacks(for: pageSession)
565	        }
566	    }
567	
568	    private func configurePageCallbacks(for pageSession: BrowserPageSession) {
569	        pageSession.configurePopupOpening { [weak self, weak pageSession] urlString in
570	            guard let self, let pageSession, self.activePageSession === pageSession else {
571	                return
572	            }
573	
574	            self.openPopupTab(urlString: urlString, privacyMode: pageSession.privacyMode)
575	        }
576	
577	        pageSession.configureContextMenuSearch(searchEngine: appPreferences.searchEngine) { [weak self] selectedText in
578	            self?.openContextMenuSearch(for: selectedText)
579	        }
580	
581	        pageSession.onURLChange = { [weak self, weak pageSession] urlString in
582	            guard let self, let pageSession else {
583	                return
584	            }
585	
586	            self.updateTabMetadata(
587	                tabID: pageSession.tabID,
588	                urlString: urlString
589	            )
590	            self.recordHistoryVisit(urlString, pageSession: pageSession)
591	        }
592	
593	        pageSession.onTitleChange = { [weak self, weak pageSession] title in
594	            guard let self, let pageSession else {
595	                return
596	            }
597	
598	            self.updateTabMetadata(
599	                tabID: pageSession.tabID,
600	                title: title
601	            )
602	            self.recordHistoryTitle(title, pageSession: pageSession)
603	        }
604	
605	        pageSession.onFaviconURLChange = { [weak self, weak pageSession] faviconURLString in
606	            guard let self, let pageSession else {
607	                return
608	            }
609	
610	            self.updateTabMetadata(
611	                tabID: pageSession.tabID,
612	                faviconURLString: faviconURLString
613	            )
614	        }
615	    }
616	
617	    private func updateTabMetadata(
618	        tabID: BrowserTab.ID,
619	        urlString: String? = nil,
620	        title: String? = nil,
621	        faviconURLString: String? = nil
622	    ) {
623	        guard let index = tabs.firstIndex(where: { $0.id == tabID }) else {
624	            return
625	        }
626	
627	        tabs[index].update(
628	            urlString: urlString,
629	            title: title,
630	            faviconURLString: faviconURLString
631	        )
632	
633	        if selectedTabID == tabID, let urlString {
634	            addressText = urlString
635	        }
636	        persistTabs()
637	    }
638	
639	    private func recordHistoryVisit(_ urlString: String, pageSession: BrowserPageSession) {
640	        guard
641	            kind == .normal,
642	            selectedTabPrivacyMode == .normal,
643	            activePageSession === pageSession
644	        else {
645	            return
646	        }
647	
648	        historyStore.recordVisit(urlString: urlString, title: pageSession.displayTitle)
649	    }
650	
651	    private func recordHistoryTitle(_ title: String, pageSession: BrowserPageSession) {
652	        guard
653	            kind == .normal,
654	            selectedTabPrivacyMode == .normal,
655	            activePageSession === pageSession
656	        else {
657	            return
658	        }
659	
660	        historyStore.updateTitle(for: pageSession.urlString, title: title)
661	    }
662	
663	    private func runFindInPage(findNext: Bool, forward: Bool) {
664	        guard findText.isEmpty == false else {
665	            return
666	        }
667	
668	        activePageSession?.findInPage(findText, forward: forward, matchCase: false, findNext: findNext)
669	    }
670	
671	    private func finishWindowCloseIfNeeded() {
672	        guard let completion = windowCloseCompletion else {
673	            return
674	        }
675	
676	        windowCloseCompletion = nil
677	        completion()
678	    }
679	
680	    private func shouldRememberClosedTab(_ tab: BrowserTab) -> Bool {
681	        kind == .normal && effectivePrivacyMode(for: tab) == .normal
682	    }
683	
684	    private func effectivePrivacyMode(for tab: BrowserTab) -> BrowserTabPrivacyMode {
685	        if kind.isIncognito, tab.privacyMode == .normal {
686	            return .incognito
687	        }
688	        return tab.privacyMode
689	    }
690	
691	    private func persistTabs() {
692	        let start = BrowserPerformanceLog.now()
693	        tabStore.save(tabs: tabs, selectedTabID: selectedTabID)
694	        BrowserPerformanceLog.duration("tabs.persist", from: start, metadata: [
695	            "tab_count": tabs.count,
696	            "selected_tab": BrowserPerformanceLog.shortID(selectedTabID)
697	        ])
698	    }
699	}
