import Foundation

/// Pure ordering rules for the browser tab array.
///
/// No UI, AppKit, or CEF dependencies, so it compiles and unit-tests in
/// isolation. `BrowserModel` delegates its reorder/normalize behavior here.
enum TabOrdering {
    /// Stable pinned-first partition: pinned tabs (keeping their existing
    /// relative order) followed by unpinned tabs (keeping theirs).
    static func normalized(_ tabs: [BrowserTab]) -> [BrowserTab] {
        tabs.filter(\.isPinned) + tabs.filter { $0.isPinned == false }
    }

    /// Reorders within one section of a pinned-first array. `fromOffsets` and
    /// `toOffset` are section-relative (as SwiftUI's `.onMove` supplies them);
    /// they are mapped to absolute indices. Assumes `tabs` already satisfies
    /// the pinned-first invariant.
    static func move(_ tabs: [BrowserTab], pinned: Bool, fromOffsets: IndexSet, toOffset: Int) -> [BrowserTab] {
        let pinnedCount = tabs.prefix(while: \.isPinned).count
        let base = pinned ? 0 : pinnedCount
        let absoluteFrom = IndexSet(fromOffsets.map { $0 + base })
        let absoluteTo = toOffset + base
        return moving(tabs, fromOffsets: absoluteFrom, toOffset: absoluteTo)
    }

    /// Foundation-only equivalent of SwiftUI's
    /// `RangeReplaceableCollection.move(fromOffsets:toOffset:)`.
    private static func moving<T>(_ array: [T], fromOffsets: IndexSet, toOffset: Int) -> [T] {
        let movingItems = fromOffsets.map { array[$0] }
        var result = array
        for index in fromOffsets.sorted(by: >) {
            result.remove(at: index)
        }
        let insertionIndex = toOffset - fromOffsets.filter { $0 < toOffset }.count
        result.insert(contentsOf: movingItems, at: insertionIndex)
        return result
    }
}
```

