import SwiftUI

/// The active page surface for a browser window: the live CEF page when a tab
/// has a session, otherwise the start page. Shared by `BrowserSplitView`
/// (compact/separate) and `SidebarBrowserLayout` (sidebar).
struct BrowserContentView: View {
    @Environment(BrowserModel.self) private var browserModel
    var topInset: CGFloat = 0

    var body: some View {
        if let pageSession = browserModel.activePageSession {
            BrowserDetailView(pageSession: pageSession, topInset: topInset)
        } else {
            StartPageView(
                isPrivate: browserModel.selectedTab?.isEphemeral ?? browserModel.kind.isIncognito,
                historyStore: browserModel.historyStore,
                topInset: topInset,
                onOpen: { browserModel.openURLString($0) }
            )
        }
    }
}
