import SwiftUI

/// Sidebar tab layout: a native `NavigationSplitView` whose sidebar is a
/// system `List` of tabs (Pinned + Tabs sections, drag-to-reorder), with the
/// address field and browser controls in a native window toolbar.
///
/// NOTE: all `NavigationSplitView` / `.toolbar` usage is intentionally
/// confined to this file (see plan hard constraints).
struct SidebarBrowserLayout: View {
    @Environment(BrowserModel.self) private var browserModel
    @State private var columnVisibility: NavigationSplitViewVisibility = .all
    @FocusState private var addressFocused: Bool

    var body: some View {
        NavigationSplitView(columnVisibility: $columnVisibility) {
            TabSidebar()
                .navigationSplitViewColumnWidth(min: 200, ideal: 240, max: 360)
        } detail: {
            BrowserContentView(topInset: 0)
        }
        .toolbar(removing: .title)
        .toolbar {
            ToolbarItemGroup(placement: .navigation) {
                NavigationControls()
            }
            ToolbarItem(placement: .principal) {
                AddressField(focused: $addressFocused, onSubmit: { submit() })
                    .frame(minWidth: 240, idealWidth: 420, maxWidth: 560)
            }
            ToolbarItemGroup(placement: .primaryAction) {
                ToolbarActions()
                PrivateWindowIndicator()
            }
        }
        .onAppear { requestFocus() }
        .onChange(of: browserModel.addressFocusRequestID) { _, _ in requestFocus() }
        .onChange(of: addressFocused) { _, focused in
            if focused == false {
                browserModel.addressText = browserModel.selectedTab?.urlString ?? ""
            }
        }
    }

    private func requestFocus() {
        DispatchQueue.main.async { addressFocused = true }
    }

    private func submit() {
        browserModel.submitAddressBar()
        addressFocused = false
    }
}

/// Native sidebar list of tabs, split into Pinned and Tabs sections.
private struct TabSidebar: View {
    @Environment(BrowserModel.self) private var browserModel

    var body: some View {
        List(selection: selectionBinding) {
            if browserModel.pinnedTabs.isEmpty == false {
                Section("Pinned") {
                    ForEach(browserModel.pinnedTabs) { tab in
                        TabSidebarRow(tab: tab, showsClose: false)
                            .tag(tab.id)
                    }
                    .onMove { offsets, destination in
                        browserModel.moveTabs(pinned: true, fromOffsets: offsets, toOffset: destination)
                    }
                }
            }

            Section("Tabs") {
                ForEach(browserModel.unpinnedTabs) { tab in
                    TabSidebarRow(tab: tab, showsClose: true)
                        .tag(tab.id)
                }
                .onMove { offsets, destination in
                    browserModel.moveTabs(pinned: false, fromOffsets: offsets, toOffset: destination)
                }
            }
        }
        .listStyle(.sidebar)
    }

    /// Single-selection binding that ignores `nil` writes, so an empty-area
    /// click can't deselect the tab and tear down the live page.
    private var selectionBinding: Binding<BrowserTab.ID?> {
        Binding(
            get: { browserModel.selectedTabID },
            set: { newValue in
                if let newValue {
                    browserModel.selectedTabID = newValue
                }
            }
        )
    }
}

/// One native sidebar row: favicon (with a privacy tint dot) + title, and a
/// hover/selected close button for unpinned tabs.
private struct TabSidebarRow: View {
    @Environment(BrowserModel.self) private var browserModel
    let tab: BrowserTab
    var showsClose: Bool = true

    @State private var isHovering = false

    private var isSelected: Bool {
        tab.id == browserModel.selectedTabID
    }

    var body: some View {
        HStack(spacing: 8) {
            FaviconIcon(
                faviconURLString: tab.faviconURLString,
                fallbackSystemName: tab.urlString == nil ? "plus" : "globe",
                size: 16
            )
            .overlay(alignment: .bottomTrailing) {
                privacyDot
            }

            Text(tab.displayTitle)
                .lineLimit(1)

            Spacer(minLength: 0)

            if showsClose && (isHovering || isSelected) {
                Button {
                    browserModel.close(tab)
                } label: {
                    Image(systemName: "xmark")
                        .font(.system(size: 9, weight: .semibold))
                        .frame(width: 16, height: 16)
                        .contentShape(Rectangle())
                }
                .buttonStyle(.plain)
                .foregroundStyle(.secondary)
                .help("Close Tab")
            }
        }
        .padding(.vertical, 2)
        .contentShape(Rectangle())
        .onHover { isHovering = $0 }
        .contextMenu { TabContextMenu(tab: tab) }
    }

    @ViewBuilder private var privacyDot: some View {
        if tab.privacyMode != .normal {
            Circle()
                .fill(tab.privacyMode.tabModeFillColor)
                .frame(width: 7, height: 7)
                .overlay {
                    Circle().strokeBorder(tab.privacyMode.tabModeBorderColor, lineWidth: 0.5)
                }
        }
    }
}
